import{_ as s,a0 as i,w as r,s as d,ao as l,I as a,a1 as n,A as p,x as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"安卓編年史（4） | LCTT x X-CMD","titleTemplate":false,"description":"安卓編年史（4） | LCTT (The history of Android) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"安卓編年史（4） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"安卓編年史（4） | LCTT (The history of Android) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"The history of Android/04 - The history of Android","title":"安卓編年史（4）","tag":"The history of Android","desc":""},"relativePath":"The history of Android/04 - The history of Android.md","filePath":"[post].md"}'),m={name:"The history of Android/04 - The history of Android.md"};function h(u,t,f,g,T,A){const e=i("Link");return r(),d("div",null,[t[14]||(t[14]=l('<h1 id="安卓編年史-4" tabindex="-1">安卓編年史（4） <a class="header-anchor" href="#安卓編年史-4" aria-label="Permalink to “安卓編年史（4）”">​</a></h1><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2013/12/horizontal.png" alt="安卓0.9顯示着橫屏的主屏幕——後續一些版本無法實現的一個特性。"></p><p><em>安卓0.9顯示着橫屏的主屏幕——後續一些版本無法實現的一個特性</em> [Ron Amadeo供圖]</p><p>儘管從功能上很難將模擬器和操作系統區分開，但安卓0.9是第一個支持橫屏顯示的版本。更讓人驚訝的是，幾乎所有東西都支持橫屏模式，在某些方面安卓0.9甚至做的比KitKat更好。在Kiakat中，主屏幕和撥號被鎖定為豎向並且無法旋轉。但在安卓0.9這裏，對任何一個應用橫向顯示都不是問題。（有誰知道怎麼把Nexus 5從Kitkat升（降）級到安卓0.9嗎？）</p><p>截圖同樣顯示了安卓0.9中的新的音量顯示設計。它拋棄了在Milestone 3中初次登場的舊鈴鐺式控制界面。那是一個巨大的，充滿屏幕的界面。實際上，安卓4.0的重新設計中讓它變得更小了，但它仍然是個問題。（你想增加音量卻因此沒法看到視頻了這種情況特別煩人。）</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2013/12/n09c2.png" alt="新通知面板，拋棄了應用快捷方式並添加了頂部部分。"></p><p><em>新通知面板，拋棄了應用快捷方式並添加了頂部部分</em> [Ron Amadeo供圖]</p><p>幾乎每個安卓版本中的通知面板都有一定的調整，安卓0.9也不例外。電池電量圖標進行了重繪，變成了黑底綠色圖標，其它的狀態欄圖標變為黑色，白色以及灰色。狀態欄左側部分明智地選擇在通知面板打開的時候顯示日期。</p><p>通知面板加入了一個新的頂部部分，它能夠顯示運營商名稱（在模擬器裏顯示“安卓”），以及一個巨大的寫着“清除通知”的按鈕，它能夠讓你不用打開應用而徹底清除通知。應用程序圖標被取消了，替換為通知到達的時間，“最新事件”文字被更換為簡單的“通知”。面板的空白部分現在是灰色的而不是之前的白色，底部的滑動條也進行了重新設計。上面兩張圖片的底部看起來並沒有對齊，但這是因為Milestone 5的通知面板在面板底部有一圈空白。安卓0.9的通知面板是完全直達底部邊緣的。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2013/12/browser4c2.png" alt="安卓0.9和0.5的瀏覽器，展現出新的無色彩菜單。"></p><p><em>安卓0.9和0.5的瀏覽器，展現出新的無色彩菜單</em> [Ron Amadeo供圖]</p><p>瀏覽器主頁現在是加載一個真正的網站，而不是像Milestone 5中那樣的本地存儲的假Google頁面。Webkit的版本升至525.10，但是看起來它似乎沒法正確渲染更現代的Google.com搜索按鈕。縱觀安卓0.9，Milestone 5中的菜單設計已經被拋棄，取而代之的是重新設計的灰色圖標。這些截圖的區別十分的明顯，因為所有的顏色都被去除了。</p><p>“更趨向於”列表式的菜單變得更高了一點，並且只是一個沒有圖標的列表而已。安卓0.9已經獲得了其它搜索方式，這次是在瀏覽器菜單裏。和主屏幕小部件，主屏幕菜單按鈕，以及瀏覽器主頁，它們共同組成了四個搜索框。谷歌從未隱藏它的主要業務是什麼，就連在它的操作系統中也是這樣。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2013/12/b4.png" alt="從左到右：安卓0.9的瀏覽器縮放控件，頁面內搜索界面，瀏覽器窗口，以及設置。"></p><p><em>從左到右：安卓0.9的瀏覽器縮放控件，頁面內搜索界面，瀏覽器窗口，以及設置</em> [Ron Amadeo供圖]</p><p>安卓0.9帶來了許多瀏覽器改進。謝天謝地縮放控件又能正常使用了，而且從瘋狂的垂直控制變成了簡單的加減按鈕。谷歌做了個符合常識的決定，將縮放控制從屏幕中間移到了屏幕底部。在這些縮放控件中，安卓在一致性方面的努力顯而易見。這些看起來是系統中唯一的圓形按鈕。</p><p>安卓0.9中的新特性“頁面內查找”會高亮顯示頁面內的關鍵詞。但總的來説，UI還是十分粗糙的——文本框比它應有的高度高了許多，“完成”按鈕帶的勾選框對這個頁面來説只是一種圖標而已。“完成”基本上是個“關閉”按鈕，這意味着它也許應該是個右對齊的“X”按鈕。</p><p>這個版本的系統沒有設置界面，但是瀏覽器最終還是有了自己的設置界面。它會有個桌面式選項的彈窗，Javascript，隱私和cookie，保存的密碼以及表單數據。甚至還有Google Gears整合（還記得Google Gears嗎？）。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/04/revisedcalls.jpg" alt="撥號盤以及打開菜單的正在通話界面。"></p><p><em>撥號盤以及打開菜單的正在通話界面</em> [Ron Amadeo供圖]</p><p>撥號和聯繫人在安卓0.9中實際上是同一個應用——兩個圖標只是打開不同的標籤而已。將聯繫人像這樣附到撥號盤表明了智能手機聯繫人的第一目的還是通話，不是短信，電子郵件，即時通訊或查找地址。最終谷歌還是會完全接受非傳統的智能手機溝通，將聯繫人和撥號分為兩個獨立的應用程序。</p><p>Milestone 5中大多數撥號盤的缺陷在安卓0.9中得到了修復。“最小化”標籤被一組正常的亮/暗標籤替代。對話氣泡式的退格鍵被替換為正常的退格圖標並集成到了撥號數字顯示界面。數字鍵變成了圓形，儘管這個系統的其它東西是圓角矩形的（至少這次文本是垂直對齊的）。谷歌還修復了Milestone 5中“-”鍵，“*”鍵和“#”鍵不平衡的問題。</p><p>在安卓0.9中點擊顯示的號碼會開始一個通話。這是十分重要的，因為這是擺脱安卓設備硬件實體“撥號”和“結束”鍵的一大步。另一方面，來電界面卻走的是完全相反的道路，去除了在安卓0.5中顯示於屏幕之上的“接聽”和“拒絕”按鍵。谷歌會花上接下來幾個版本的時間去摸索在特定的顯示之下是否需要硬件實體撥號鍵。但是直到安卓2.0和摩托羅拉Droid面世，實體撥號按鈕才最終變成了可選選項。</p><p>來電界面的所有選項隱藏在目錄按鈕之後。Milestone 5不支持距離傳感器，所以它採取了簡單粗暴的路線，在通話過程中禁用觸摸屏。安卓0.9為G1開發，它有個距離傳感器。最終谷歌沒有在通話的時候禁用觸摸傳感器。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2013/12/CONTACTS.png" alt="安卓0.9和0.5中獨立的聯繫人界面和聯繫人編緝界面。"></p><p><em>安卓0.9和0.5中獨立的聯繫人界面和聯繫人編緝界面</em> [Ron Amadeo供圖]</p><p>Milestone 5的一些聯繫人信息有令人困惑的標籤，像電子郵件只被打上“主要的”標籤而不是“主電子郵箱”標籤。安卓0.9用各部分的水平標題糾正了這個錯誤。而且現在左側的每個聯繫人類型都有了手形圖標（Action icons）。</p><p>編緝聯繫人界面如今是個更加繁忙的地方。每個輸入框都有刪除按鈕，特定聯繫人鈴聲，一個顯示在屏幕上的“更多信息”按鈕用來添加輸入框，一個是否將通話直接發送到語音信箱的複選框，以及在列表底部的“保存”和“放棄修改”按鈕。從功能上來説，相對於舊版本這是個巨大的進步，但它看起來仍然很混亂。</p><hr><p><img src="http://cdn.arstechnica.net/wp-content//uploads/authors/ron-amadeo-sq.jpg" alt="Ron Amadeo"></p>',30)),a("p",null,[n(e,{href:"http://arstechnica.com/author/ronamadeo"},{default:p(()=>[...t[0]||(t[0]=[o("Ron Amadeo",-1)])]),_:1}),t[1]||(t[1]=o(" / Ron是Ars Technica的評論編緝，專注於安卓系統和谷歌產品。他總是在追尋新鮮事物，還喜歡拆解事物看看它們到底是怎麼運作的。",-1))]),a("p",null,[n(e,{href:"https://twitter.com/RonAmadeo"},{default:p(()=>[...t[2]||(t[2]=[o("@RonAmadeo",-1)])]),_:1})]),t[15]||(t[15]=a("hr",null,null,-1)),a("p",null,[t[4]||(t[4]=o("via: ",-1)),n(e,{href:"http://arstechnica.com/gadgets/2014/06/building-android-a-40000-word-history-of-googles-mobile-os/4/"},{default:p(()=>[...t[3]||(t[3]=[o("http://arstechnica.com/gadgets/2014/06/building-android-a-40000-word-history-of-googles-mobile-os/4/",-1)])]),_:1})]),a("p",null,[t[7]||(t[7]=o("譯者：",-1)),n(e,{href:"https://github.com/alim0x"},{default:p(()=>[...t[5]||(t[5]=[o("alim0x",-1)])]),_:1}),t[8]||(t[8]=o(" 校對：",-1)),n(e,{href:"https://github.com/wxy"},{default:p(()=>[...t[6]||(t[6]=[o("wxy",-1)])]),_:1})]),a("p",null,[t[11]||(t[11]=o("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[9]||(t[9]=[o("LCTT",-1)])]),_:1}),t[12]||(t[12]=o(" 原創翻譯，",-1)),n(e,{href:"http://linux.cn/"},{default:p(()=>[...t[10]||(t[10]=[o("Linux中國",-1)])]),_:1}),t[13]||(t[13]=o(" 榮譽推出",-1))])])}const w=s(m,[["render",h]]);export{x as __pageData,w as default};
